// ===== 설정 (여기만 수정하세요) =====
const CONFIG = {
  API_KEY: 'AIzaSyDI0pjUJBjW2zorcIDkL7G1LCsd21gNmNQ',
  MAX_VIDEOS_PER_QUERY: 50,          // 검색어당 영상 수 (최대 50, 할당량은 10개일 때와 같음)
  PUBLISHED_AFTER: '2021-01-01T00:00:00Z',
  MAX_TOTAL_VIDEOS: 800,             // 댓글을 가져올 영상 최대 수 (많을수록 오래 걸림)
  SAMPLE_SIZE: 400,                  // 사람이 읽을 무작위 표본 수
  RANDOM_SEED: 20261002,             // 같은 값이면 같은 표본이 뽑힘 (재현 가능)
  // 채널 단위 수집: 이 영상들이 속한 채널의 '에어컨 관련 영상 전체'를 가져옵니다.
  // 기본값: LG전자서비스 공식 채널(1차에서 댓글이 가장 많던 영상), 냉난방이야기, 에어컨의 모든것 청년
  CHANNEL_SEED_VIDEO_IDS: ['wUWv0xFiDrA', 'cuXCjWqcYPs', 'upo0-x0nG-Y'],
};

// 1차·2차 검색어 통합 (검색 1회 = 할당량 100, 하루 기본 10,000)
const QUERIES = [
  // 증상
  'LG 에어컨 안 시원함', '휘센 냉방 약함', '휘센 에어컨 냄새', 'LG 에어컨 쉰내', 'LG 에어컨 물 떨어짐', '휘센 물샘',
  'LG 에어컨 소음', '휘센 실외기 소음', '휘센 에러코드', 'LG 에어컨 CH05', 'LG 에어컨 CH38', '휘센 실외기 안 돌아요',
  'LG 에어컨 저절로 꺼짐', '휘센 에어컨 전원 안 켜짐', 'LG 에어컨 성에 얼음', '휘센 자동건조', 'LG 에어컨 필터 청소',
  '휘센 냉매 가스 충전', 'LG 에어컨 고장 원인',
  // 스마트진단·ThinQ
  'LG 에어컨 스마트진단', '씽큐 스마트진단 에어컨', '휘센 자가진단', 'LG 씽큐 에어컨 등록', 'LG 씽큐 연결 안됨',
  // 상담·AS
  'LG 에어컨 AS 후기', 'LG전자 서비스 접수 후기', 'LG 에어컨 출장비',
  // 자가 해결
  '에어컨 기사 부르기 전 확인', 'LG 에어컨 고장 아닌 경우', 'LG 에어컨 자가점검', 'LG 에어컨 리모컨 실내기 선택',
];

return QUERIES.map(q => ({ json: { query: q, ...CONFIG } }));

// 검색 결과 → 영상 목록 (LG 관련만, 중복 제거)
const RELATED_RE = /LG|엘지|휘센|whisen|오브제|씽큐|thinq|스마트\s*진단|자가\s*진단|자가\s*점검/i;
const queries = $('설정').all();
const decode = s => String(s || '').replace(/&quot;/g, '"').replace(/&#39;/g, "'").replace(/&amp;/g, '&').replace(/&lt;/g, '<').replace(/&gt;/g, '>');
const map = new Map();
$input.all().forEach((item, i) => {
  const idx = (item.pairedItem && item.pairedItem.item !== undefined) ? item.pairedItem.item : i;
  const q = ((queries[idx] || {}).json || {}).query || '';
  for (const v of (item.json.items || [])) {
    const id = v.id && v.id.videoId; if (!id) continue;
    const sn = v.snippet || {};
    const title = decode(sn.title);
    if (!RELATED_RE.test(title + ' ' + decode(sn.description) + ' ' + decode(sn.channelTitle))) continue;
    if (map.has(id)) { map.get(id).hits += 1; map.get(id).queries.push(q); continue; }
    map.set(id, { videoId: id, videoTitle: title, channel: decode(sn.channelTitle), source: '검색', hits: 1, queries: [q] });
  }
});
const out = [...map.values()].map(v => ({ json: { ...v, queries: v.queries.join(' | ') } }));
return out.length ? out : [{ json: { empty: true } }];

// 시드 영상 → 채널의 '업로드 전체' 재생목록 ID (채널ID UC... → UU...)
const map = new Map();
for (const item of $input.all()) for (const v of (item.json.items || [])) {
  const sn = v.snippet || {}, ch = sn.channelId;
  if (ch && ch.startsWith('UC') && !map.has(ch)) map.set(ch, { playlistId: 'UU' + ch.slice(2), channel: sn.channelTitle || '' });
}
const out = [...map.values()].map(j => ({ json: j }));
return out.length ? out : [{ json: { playlistId: 'NONE', channel: '' } }];

// 검색 영상 + 채널 영상(에어컨 관련 제목만) 합치기 → 댓글 가져올 영상 목록
const AIRCON_TITLE = /에어컨|에어콘|휘센|whisen|냉방|냉난방|실외기|실내기|씽큐|thinq|스마트\s*진단|자가\s*진단|자가\s*점검|시스템\s*에어/i;
const cfg = $('설정').first().json;
const map = new Map();
for (const it of $('검색 결과 정리').all()) if (it.json.videoId) map.set(it.json.videoId, { ...it.json });
for (const item of $input.all()) for (const p of (item.json.items || [])) {
  const sn = p.snippet || {};
  const id = (sn.resourceId || {}).videoId;
  if (!id || !AIRCON_TITLE.test(sn.title || '')) continue;
  if (map.has(id)) { map.get(id).source = '검색+채널'; map.get(id).hits += 1; continue; }
  map.set(id, { videoId: id, videoTitle: sn.title, channel: sn.channelTitle || sn.videoOwnerChannelTitle || '', source: '채널', hits: 1, queries: '' });
}
// 여러 검색어에 걸린 영상을 우선해서 최대 개수까지
const list = [...map.values()].sort((a, b) => b.hits - a.hits).slice(0, cfg.MAX_TOTAL_VIDEOS);
return list.map(v => ({ json: { ...v, apiKey: cfg.API_KEY } }));

// 댓글 펼치기 → 넓은 키워드 필터 → 신호 태깅 → 무작위 표본 표시
const cfg = $('설정').first().json;
const MIN_LEN = 8;

// 넓게 거르는 필터: 놓치지 않는 쪽(재현율)을 우선. 정확한 판정은 표본을 사람이 읽어서 함.
const KEEP = /\?|까요|나요|가요|는지|인가요|되나요|어떻게|어떡|왜|모르|원인|고장|정상|문제|안\s*(돼|되|나와|켜|꺼|시원|돌)|에러|오류|CH\s?\d|냄새|곰팡|쉰내|물이?\s*(새|떨어)|누수|소음|시끄|소리|진단|씽큐|thinq|앱|어플|고객\s*센터|상담|접수|기사|a\s*\/?\s*s|수리|출장|서비스|리모컨|리모콘|실외기|냉매|가스|해결|됐어요|되네요|부를|불러/i;
const DROP_ONLY = /^(감사|고맙|좋은\s*(영상|정보)|잘\s*봤|최고|구독|좋아요)/; // 질문·증상 없는 단순 인사

const SYMPTOMS = {
  '냉방불량': /찬\s*바람이?\s*안|안\s*시원|시원하지\s*않|냉방이?\s*(약|안)|미지근/, '냄새': /냄새|쉰내|악취|곰팡/,
  '물샘': /물이?\s*(새|샘|떨어|뚝뚝|흘러|넘)|누수|배수/, '소음': /소음|시끄|소리가|소리\s*(나|남)|덜덜|진동/,
  '에러코드': /CH\s?-?\d{1,3}|에러\s*코드|오류\s*코드|에러\s*뜨|에러가/i, '작동이상': /꺼져|꺼짐|꺼지|안\s*켜|안\s*돌|작동\s*(이\s*)?안|멈춰|멈춤|깜빡/,
  '냉매·결빙': /성에|얼음|결빙|냉매|가스\s*(충전|보충|부족)/, '리모컨·설정': /리모컨|리모콘|실내기\s*선택|예약/, '청소·필터': /청소|필터|세척|분해/,
};
const SIG = {
  '원인모름': /왜\s*(그런|이러|이렇|그럴|안|자꾸|계속)|원인이|원인을|뭐가\s*문제|무슨\s*문제|이유가|고장\s*인가|고장인지|정상\s*인가|정상인지|이게\s*맞나|모르겠/,
  '다음행동모름': /어떻게\s*(해야|하면|하나요|하죠)|어떡하|어쩌죠|해야\s*(하나요|할까|되나|돼요|되나요)|불러야|방법\s*(이|좀)?\s*(있|알려|없)|해결\s*(방법|이\s*안|못)|알려\s*주세요|도와\s*주세요/,
  '자가해결': /해결\s*(했|됐|되었)|됐어요|되네요|되더라|작동\s*(하네|되네|됐)|고쳤/,
  'AS부르기직전': /(기사|as|a\/s|서비스)\s*(를\s*)?(부르|부를|신청|접수)[^.?!]{0,15}(뻔|전에|했는데|하려다|했다가)|부를\s*뻔|부르려다/i,
  '스마트진단': /스마트\s*진단|자가\s*진단|씽큐\s*진단|thinq\s*진단|진단\s*(결과|했|해\s*보|돌려|기능)/i,
  'ThinQ': /씽큐|thinq|띵큐|어플|앱으로/i,
  '상담·고객센터': /고객\s*센터|상담|1544|챗봇|1:1|콜센터|접수/,
  'AS·기사': /기사|a\s*\/?\s*s|출장|수리\s*(비|받|기사)/i,
};

const videos = new Map($('영상 목록 합치기').all().map(i => [i.json.videoId, i.json]));
const seen = new Set(), seenText = new Set(), rows = [];
const Y = b => b ? 'Y' : '';
function add(sn, id, isReply, parentText, replyCount, videoId) {
  if (!sn || seen.has(id)) return; seen.add(id);
  const text = String(sn.textOriginal || sn.textDisplay || '').replace(/\s+/g, ' ').trim();
  if (text.length < MIN_LEN || seenText.has(text)) return;
  if (!KEEP.test(text)) return;
  if (DROP_ONLY.test(text) && !/\?|왜|어떻게|안\s*(돼|되)/.test(text) && text.length < 40) return;
  if (/https?:\/\//.test(text) && /구매|할인|쿠팡|링크|교육|창업/.test(text)) return;
  seenText.add(text);
  const v = videos.get(videoId) || {};
  const row = {
    '표본': '', '표본순번': '',
    '수집경로': v.source || '', '영상제목': v.videoTitle || '', '채널': v.channel || '',
    '댓글URL': `https://www.youtube.com/watch?v=${videoId}&lc=${id}`,
    '구분': isReply ? '답글' : '댓글', '원댓글': isReply ? parentText : '', '댓글내용': text,
    '좋아요': sn.likeCount || 0, '작성일': String(sn.publishedAt || '').slice(0, 10),
    '증상분류': Object.entries(SYMPTOMS).filter(([, re]) => re.test(text)).map(([k]) => k).join(', '),
  };
  for (const [k, re] of Object.entries(SIG)) row['키워드_' + k] = Y(re.test(text));
  row['댓글ID'] = id;
  rows.push(row);
}
for (const item of $input.all()) for (const t of (item.json.items || [])) {
  const s = t.snippet || {}, top = s.topLevelComment || {};
  const topText = String((top.snippet || {}).textOriginal || '').replace(/\s+/g, ' ').trim();
  add(top.snippet, top.id, false, '', s.totalReplyCount, s.videoId);
  for (const r of ((t.replies || {}).comments || [])) add(r.snippet, r.id, true, topText.slice(0, 300), 0, s.videoId);
}

// 재현 가능한 무작위 표본 (시드 고정 셔플)
let seed = cfg.RANDOM_SEED >>> 0;
const rand = () => { seed = (seed + 0x6D2B79F5) >>> 0; let t = seed; t = Math.imul(t ^ (t >>> 15), t | 1); t ^= t + Math.imul(t ^ (t >>> 7), t | 61); return ((t ^ (t >>> 14)) >>> 0) / 4294967296; };
const order = rows.map((_, i) => i);
for (let i = order.length - 1; i > 0; i--) { const j = Math.floor(rand() * (i + 1)); [order[i], order[j]] = [order[j], order[i]]; }
order.slice(0, cfg.SAMPLE_SIZE).forEach((ri, k) => { rows[ri]['표본'] = 'Y'; rows[ri]['표본순번'] = k + 1; });

rows.sort((a, b) => (a['표본순번'] || 1e9) - (b['표본순번'] || 1e9));
return rows.map(r => ({ json: r }));
